<script lang="ts">
 import { onMount } from 'svelte';
 import { api } from '../lib/api';
 import type {Analysis,Comparison,Page,Query,RequestRecord} from '../lib/types';
 import { percentileLabel, percentileThreshold } from '../lib/slowness';
 import { echarts, palette } from '../lib/charts';
 import { theme } from '../lib/theme.svelte';
 import { trafficData } from '../lib/traffic';
 // scope narrows the slowest-request list (not the traffic chart) to one operation; without it the list covers the whole comparison.
 let {analysis,zone,sourceLabels,onContext,cohort=null,scope=null}:{analysis:Analysis;zone:string;sourceLabels:Map<string,string>;onContext:(row:RequestRecord)=>void;cohort?:Comparison|null;scope?:{controller?:string;action?:string;kind:Query['kind'];label:string}|null}=$props();
 let threshold=$state(1000),metric=$state<'p95'|'median'|'max'>('p95'),log=$state(true),selected=$state<number|null>(null),windowPage=$state(0),mode=$state<'ms'|'p95'|'p99'>('ms'),loaded=$state<{query:Query;min:number|null;label:string}|null>(null);
 let node=$state<HTMLDivElement>(),chart=$state<ReturnType<typeof echarts.init>>(),page=$state<Page|null>(null),loading=$state(false),error=$state(''),loadedStart=$state(''),loadedEnd=$state('');
 let controller:AbortController|undefined,sequence=0;
 const validThreshold=$derived(Number.isFinite(threshold)&&threshold>0);
 const cohortMin=$derived(mode==='ms'?null:percentileThreshold(cohort?.current,mode)),minimum=$derived(mode==='ms'?(validThreshold?threshold:null):cohortMin),canLoad=$derived(minimum!=null);
 const data=$derived(trafficData(analysis.query,analysis.loadWindows??[],validThreshold?threshold:1000,metric));
 const selectedWindow=$derived(selected==null?null:data.windows.find(row=>row.at===selected)??null);
 const scopeStart=$derived(selectedWindow?new Date(selectedWindow.start).toISOString():analysis.query.start),scopeEnd=$derived(selectedWindow?new Date(selectedWindow.end).toISOString():analysis.query.end);
 const baseline=$derived(new Map(analysis.apis.map(row=>[JSON.stringify([row.sourceId,row.controller,row.action,row.kind,row.outcome]),row.reference])));
 const stamp=(at:number|string)=>new Intl.DateTimeFormat(undefined,{timeZone:zone,month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(at));
 const ms=(value:number|null|undefined)=>value==null?'Unavailable':value>=1000?(value/1000).toLocaleString(undefined,{maximumFractionDigits:2})+' s':value.toLocaleString(undefined,{maximumFractionDigits:1})+' ms';
 const duration=(row:RequestRecord)=>analysis.query.metric==='api'?row.apiTimeMs:row.durationMs;
 function reference(row:RequestRecord){const r=baseline.get(JSON.stringify([row.sourceId,row.controller,row.action,row.kind,row.outcome]));return r&&r.count>=20&&r.p95?.valueMs!=null&&r.p95.valueMs>0&&duration(row)!=null?'≈ '+(duration(row)!/r.p95.valueMs).toFixed(2)+'×':'Unavailable';}
 function slowQuery():Query{const base:Query={...analysis.query,start:scopeStart,end:scopeEnd,...(scope?{kind:scope.kind,...(scope.controller!==undefined?{controller:scope.controller}:{}),...(scope.action!==undefined?{action:scope.action}:{})}:{})};return mode==='ms'||!cohort?base:{...base,sourceIds:[cohort.sourceId],controller:cohort.controller,action:cohort.action,kind:cohort.kind as Query['kind'],outcome:cohort.outcome as Query['outcome']};}
 // In percentile mode the list is read for the selected group alone (slowQuery), so the heading names that group, not the operation or the whole comparison.
 const narrowed=$derived(mode!=='ms'&&cohort?cohort:null);
 const headingScope=$derived(narrowed?'Selected group '+[narrowed.controller+'.'+narrowed.action,narrowed.kind,narrowed.outcome].filter(Boolean).join(' · '):scope?scope.label:'All operations in this comparison');
 const rowKey=(row:RequestRecord)=>row.sourceId+':'+row.id;
 async function loadSlowest(more=false){if(more?!page?.nextCursor||!loaded:!canLoad)return;const request=more?loaded!:{query:slowQuery(),min:minimum,label:mode==='ms'?'at least '+ms(minimum):percentileLabel(mode as 'p95'|'p99',minimum!)};const cursor=more?page!.nextCursor:'';controller?.abort();controller=new AbortController();const run=++sequence;loading=true;error='';if(!more)page=null;try{const result=await api.slowest(request.query,controller.signal,{cursor,minMs:request.min});if(run!==sequence)return;if(more&&page){const seen=new Set(page.rows.map(rowKey));page={...result,rows:[...page.rows,...result.rows.filter(row=>!seen.has(rowKey(row)))]};}else page=result;loaded=request;loadedStart=request.query.start;loadedEnd=request.query.end;}catch(cause){if(run===sequence&&!(cause instanceof DOMException&&cause.name==='AbortError'))error=cause instanceof Error?cause.message:'Could not load slowest requests.';}finally{if(run===sequence)loading=false;}}
 function selectWindow(at:number|null){sequence++;controller?.abort();loading=false;error='';page=null;loaded=null;loadedStart='';loadedEnd='';selected=at;}
 $effect(()=>{analysis;scope?.label;cohort?.key;sequence++;controller?.abort();loading=false;page=null;loaded=null;selected=null;loadedStart='';loadedEnd='';error='';windowPage=0;});
 onMount(()=>{if(!node)return;chart=echarts.init(node);const observer=new ResizeObserver(()=>chart?.resize());observer.observe(node);chart.on('click',(event)=>{if(event.seriesType==='scatter'&&Array.isArray(event.value)){selectWindow(Number(event.value[2]));void loadSlowest();}});return()=>{sequence++;controller?.abort();observer.disconnect();chart?.dispose();};});
 $effect(()=>{if(!chart)return;void theme.epoch;const p=palette(),axis={axisLine:{lineStyle:{color:p.axisLine}},axisLabel:{color:p.text2},nameTextStyle:{color:p.text2},splitLine:{lineStyle:{color:p.grid}}};const points=data.points.filter(row=>!log||row.latency!>0);chart.setOption({animation:false,textStyle:{color:p.text2},tooltip:{trigger:'item',renderMode:'richText',confine:true,formatter:(item:any)=>{const v=item.value;if(item.seriesType==='line')return `Traffic ${v[2]}–${v[3]-1} starts/window\n${v[4]} of ${v[5]} measured windows (${v[1].toFixed(1)}%) had a slow request`;return `${stamp(v[7])}–${stamp(v[3])}\n${v[0]} request starts · ${v[4]} usable timings\n${metric}: ${ms(v[1])} · longest: ${ms(v[5])}\n${v[6]?'Partial boundary window':'Complete window'}\nClick to load slowest requests`; }},legend:{top:0,type:'scroll',textStyle:{color:p.text2},pageTextStyle:{color:p.text2},data:['No observed slow request','Contains a slow request','Slow windows (%)']},grid:{left:70,right:65,top:60,bottom:80},xAxis:{type:'log',logBase:2,name:'Requests started in each time window',nameLocation:'middle',nameGap:35,min:1,...axis},yAxis:[{type:log?'log':'value',name:metric==='p95'?'Slower-end time (P95 ms)':metric==='median'?'Typical time (median ms)':'Longest time (ms)',nameLocation:'middle',nameGap:48,...axis},{type:'value',name:'Slow windows %',min:0,max:100,...axis,splitLine:{show:false}}],dataZoom:[{type:'inside',xAxisIndex:0,filterMode:'none'},{type:'slider',xAxisIndex:0,bottom:8,height:18,filterMode:'none'}],series:[...[[false,'No observed slow request',p.accent],[true,'Contains a slow request',p.bad]].map(([slow,name,color])=>({name,type:'scatter',symbolSize:9,itemStyle:{color,opacity:.8},data:points.filter(row=>row.slow===slow).map(row=>[row.count,row.latency,row.at,row.end,row.timings,row.max,row.partial,row.start])})),{name:'Slow windows (%)',type:'line',yAxisIndex:1,connectNulls:false,lineStyle:{color:p.warn},itemStyle:{color:p.warn},data:data.buckets.map(b=>[b.lower*Math.sqrt(2),b.percent,b.lower,b.upper,b.slow,b.measured])}]},true);});
</script>
<section class="data-section traffic-slowness" aria-label="Traffic versus slowness">
 <div class="section-heading"><div><h3>Did requests get slower when traffic increased?</h3><p>Each dot is one time window. Farther right means more requests; higher means longer response times.</p></div></div>
 <div class="volume-controls"><label>Slow means longer than (ms)<input aria-label="Slow request threshold in milliseconds" type="number" min="1" bind:value={threshold} /></label><label>Response time to plot<select aria-label="Traffic latency statistic" bind:value={metric}><option value="p95">Slower-end time (P95)</option><option value="median">Typical time (median)</option><option value="max">Longest request</option></select></label><label>Only show requests slower than<select aria-label="Minimum for the slowest requests" bind:value={mode}><option value="ms">the slow threshold on the left</option><option value="p95" disabled={percentileThreshold(cohort?.current,'p95')==null}>P95 of the selected API group (histogram estimate)</option><option value="p99" disabled={percentileThreshold(cohort?.current,'p99')==null}>P99 of the selected API group (histogram estimate)</option></select></label><label class="traffic-log"><input type="checkbox" bind:checked={log} /> Logarithmic response-time scale</label><button class="secondary-button" onclick={()=>{selectWindow(null);chart?.dispatchAction({type:'dataZoom',start:0,end:100});}}>Reset zoom and window</button></div>
 {#if !validThreshold}<p class="inline-error" role="alert">Enter a threshold greater than zero. The chart uses 1,000 ms until this is corrected{mode==='ms'?', and slowest requests cannot be loaded':''}.</p>{/if}
 {#if scope&&!narrowed}<p class="sample-note">The slowest requests below are limited to {scope.label}. The chart still counts every request in this comparison, because traffic and slowness are compared across all operations.</p>{/if}
 {#if mode!=='ms'}<p class="sample-note">{cohortMin!=null?percentileLabel(mode,cohortMin)+'. Only that API group, request type and outcome are read.':'Select an API group with enough measured requests (20 for P95, 100 for P99) to use a percentile minimum. Choose the time on the left to continue without one.'}</p>{/if}
 <div class="activity-explanation"><p><strong>Red means at least one request exceeded {ms(validThreshold?threshold:1000)}.</strong> A window can be red even if most requests were fast. P95 estimates the time within which about 95 of 100 measured requests finished. Median means half finished sooner. The initial one-second threshold is adjustable; it is not a health verdict.</p><details class="traffic-method"><summary>How the windows and percentages are calculated</summary><p>The orange line shows the share of measured windows containing a slow request at similar traffic levels, grouped into doubling traffic ranges. Hover for the number of windows behind each percentage. Partial boundary windows appear as dots but are excluded from this line. Missing timings cannot establish that a window was fast. Percentiles from fewer than 20 timings are less reliable.</p><p>Window size: <strong>{analysis.query.bucketSeconds} seconds</strong>, from this comparison’s chart interval. Finer timing requires a finer interval and a new comparison. All selected sources, API filters and {analysis.query.metric==='api'?'API processing':'full request'} timing apply. Mixed API workloads can change the result; correlation does not prove traffic caused slowness. {log?'Zero-duration dots are omitted on the logarithmic scale; turn it off to include them.':''}</p></details></div>
 {#if analysis.sources.some(source=>!source.ok)}<div class="inline-error" role="status">Incomplete source coverage: only successful sources are represented. Missing activity can change the apparent traffic/slowness relationship.</div>{/if}
 {#if analysis.loadWindows==null}<p class="sample-note">Run analysis again to load traffic and timing windows.</p>{:else if !data.points.length}<p class="sample-note">No windows with usable timings to plot. Request counts alone cannot establish response speed.</p>{/if}
 <div class="traffic-chart" bind:this={node} role="img" aria-label={'Traffic versus '+metric+' response time for '+data.points.length+' measured windows. Exact windows are available in the table below.'}></div>
 <details class="traffic-windows"><summary>Exact time windows and traffic ranges</summary><p>{data.unmeasured} nonempty windows have no usable timings. Time zone: {zone}. Each interval includes its start and excludes its end.</p><div class="volume-table-wrap"><table class="volume-table"><thead><tr><th>Time window</th><th>Requests</th><th>Usable timings</th><th>Plotted time</th><th>Longest</th><th>Inspect</th></tr></thead><tbody>{#each data.windows.slice(windowPage*10,windowPage*10+10) as row}<tr><th>{stamp(row.start)}–{stamp(row.end)}{row.partial?' (partial)':''}</th><td>{row.count}</td><td>{row.timings}</td><td>{ms(row.latency)}</td><td>{ms(row.max)}</td><td><button class="quiet-button" onclick={()=>{selectWindow(row.at);void loadSlowest();}}>Inspect window</button></td></tr>{/each}</tbody></table></div><div class="pagination-row"><button class="secondary-button" disabled={!windowPage} onclick={()=>windowPage--}>Earlier windows</button><span>Page {windowPage+1} of {Math.max(1,Math.ceil(data.windows.length/10))}</span><button class="secondary-button" disabled={(windowPage+1)*10>=data.windows.length} onclick={()=>windowPage++}>Later windows</button></div><ul>{#each data.buckets as b}<li>{b.lower}–{b.upper-1} starts: {b.slow}/{b.measured} measured complete windows contained a slow request ({b.percent.toFixed(1)}%).</li>{/each}</ul></details>
 <div class="section-heading"><div><h3>Slowest requests and surrounding activity</h3><p>{headingScope} · {selectedWindow?'Selected window':'Full investigation'}: {stamp(scopeStart)}–{stamp(scopeEnd)} ({zone}).</p></div><button class="secondary-button" disabled={loading||!canLoad} onclick={()=>loadSlowest()}>{loading&&!page?'Reading slowest requests…':'Load 50 slowest requests'}</button>{#if loading}<button class="quiet-button" onclick={()=>{sequence++;controller?.abort();loading=false;}}>Cancel</button>{/if}</div>
 <p class="activity-explanation">This reads timing metadata for the selected interval, ranks by {analysis.query.metric==='api'?'API processing':'full request'} duration across sources, and returns at most 50 records per page, only those at or above the chosen minimum; Load more continues from the last record. Baseline comparison uses this request’s source, API, request type and outcome with at least 20 earlier timings; it is an estimate against the earlier P95, not proof of a cause. Audit write time plus API time make up the full request duration; payload recording happens after the response and is not latency. Choose Nearby activity to inspect overlapping APIs and jobs.</p>
 {#if error}<div class="inline-error" role="alert">{error}</div>{/if}
 {#if page}<p class="volume-summary">{page.rows.length} records · {stamp(loadedStart)}–{stamp(loadedEnd)}{loaded?' · '+loaded.label:''}{page.nextCursor?' · More matching requests exist.':''}</p>{#if page.sources.some(source=>!source.ok)}<div class="inline-error" role="alert">Incomplete slowest-request results.{#each page.sources.filter(source=>!source.ok) as failed}<p>{sourceLabels.get(failed.sourceId)??failed.sourceId}: {failed.error}</p>{/each}</div>{/if}<div class="volume-table-wrap"><table class="volume-table"><thead><tr><th>Started</th><th>Duration</th><th>API / source</th><th>Versus earlier P95</th><th>API / audit time</th><th>Investigate</th></tr></thead><tbody>{#each page.rows as row(row.sourceId+':'+row.id)}<tr><td>{row.initiatedAt?stamp(row.initiatedAt):'Unknown'}</td><td class:traffic-slow={duration(row)!=null&&duration(row)!>=(loaded?.min??(validThreshold?threshold:1000))}>{ms(duration(row))}</td><th>{row.controller}.{row.action}<small>{sourceLabels.get(row.sourceId)??row.sourceId} · {row.kind} · {row.outcome}</small></th><td>{reference(row)}</td><td>{ms(row.apiTimeMs)} / {ms(row.auditCreateTimeMs)}</td><td><button class="quiet-button" disabled={!row.initiatedAt} onclick={()=>onContext(row)}>Nearby activity</button></td></tr>{/each}</tbody></table></div>{#if page.nextCursor}<div class="pagination-row"><button class="secondary-button" disabled={loading} onclick={()=>loadSlowest(true)}>{loading?'Reading more requests…':'Load more'}</button></div>{/if}{#if !page.rows.length}<p class="sample-note">No requests {loaded?.min!=null?'at or above '+ms(loaded.min)+' ':''}with usable timings for the chosen measure were reported by successful sources.</p>{/if}{:else if !loading}<p class="sample-note">Load the slowest requests, click a dot, or inspect an exact time window to begin.</p>{/if}
</section>



